/** Captures native outbound feedback at real player connections in an isolated live match. */
public final class FeedbackDropChecks {
    private FeedbackDropChecks() { }
    private static State running;
    private static String stopEpoch;
    private static ItemEntity stopToken;
    private static ServerPlayer stopVictim;
    private static void require(boolean value,String message){if(!value)throw new IllegalStateException("Feedback drops: "+message);}
    private static final class Recording extends Connection {
        final ServerPlayer player;final List<Packet<?>> sent=new ArrayList<>();
        Recording(ServerPlayer player){super(PacketFlow.SERVERBOUND);this.player=player;}
        @Override public boolean isMemoryConnection(){return true;}
        @Override public boolean isConnected(){return true;}
        @Override public PacketListener getPacketListener(){return player.connection;}
        @Override public void send(Packet<?> packet,io.netty.channel.ChannelFutureListener listener,boolean flush){sent.add(packet);}
        // Native resumeFlushing calls this every server tick. Capture is immediate and has
        // no transport buffer/channel to flush; retain the real listener and packet context.
        @Override public void flushChannel(){ }
    }
    private static final class Swap implements AutoCloseable {
        final ServerPlayer player;final ServerGamePacketListenerImpl previous;final Recording recorder;
        Swap(GameController game,ServerPlayer player){this.player=player;previous=player.connection;recorder=new Recording(player);var listener=new ServerGamePacketListenerImpl(game.server(),recorder,player,new CommonListenerCookie(player.getGameProfile(),0,player.clientInformation(),false));player.connection=listener;}
        public void close(){player.connection=previous;previous.resetPosition();}
    }
    private static ItemEntity token(ServerLevel level,Vec3 at,int count,ServerPlayer owner,LbcFeedbackDropItem.Kind kind){var item=new ItemEntity(level,at.x,at.y,at.z,new ItemStack(kind.item(),count));item.setThrower(owner);item.setNoGravity(true);item.setDeltaMovement(Vec3.ZERO);item.setPickUpDelay(1000);require(level.addFreshEntity(item),"native token admission");return item;}
    private static int packetIndex(Recording recording, Packet<?> packet){for(int i=0;i<recording.sent.size();i++)if(recording.sent.get(i)==packet)return i;return -1;}
    private static List<ClientboundSoundPacket> sounds(Recording recording,String name){return recording.sent.stream().filter(ClientboundSoundPacket.class::isInstance).map(ClientboundSoundPacket.class::cast).filter(p->p.getSound().value().location().toString().equals(name)).toList();}
    private static List<ClientboundSetTitleTextPacket> titles(Recording recording){return recording.sent.stream().filter(ClientboundSetTitleTextPacket.class::isInstance).map(ClientboundSetTitleTextPacket.class::cast).toList();}
    private static List<ClientboundSystemChatPacket> broadcasts(Recording recording){return recording.sent.stream().filter(ClientboundSystemChatPacket.class::isInstance).map(ClientboundSystemChatPacket.class::cast).filter(p->p.content().getSiblings().stream().anyMatch(c->c.getContents() instanceof net.minecraft.network.chat.contents.TranslatableContents t && t.getKey().equals("died_from_cum"))).toList();}
    private static final class State implements AutoCloseable {
        final GameController game;final ServerLevel level;final ServerPlayer alpha,beta;final GameChecks.WandThirdPlayerState alphaState,betaState;
        final Vec3 origin;final List<ItemEntity> tokens=new ArrayList<>();final Set<Entity> existing=Collections.newSetFromMap(new IdentityHashMap<>());
        Swap alphaSwap,betaSwap;ItemEntity stack,paused;int phase,lastTick,wait,counter;
        State(GameController game){this.game=game;level=game.maps().level();alpha=game.server().getPlayerList().getPlayer(GameChecks.offlineUuid("TestAlpha"));beta=game.server().getPlayerList().getPlayer(GameChecks.offlineUuid("TestBeta"));require(game.playing() && alpha!=null && beta!=null && game.allowDamage(beta),"actual match participants");for(var p:List.of(alpha,beta))for(var name:List.of("scared","lookback","twitching","piss"))require(game.items().psycho().effectValue(p,name)==0,"fixture owns initially clean Psycho state "+p.getScoreboardName()+"/"+name);alphaState=new GameChecks.WandThirdPlayerState(alpha,game.items().mana());betaState=new GameChecks.WandThirdPlayerState(beta,game.items().mana());origin=new Vec3(Math.floor(alpha.getX()/16)*16+8.37,270.7,Math.floor(alpha.getZ()/16)*16+8.81);level.getAllEntities().forEach(existing::add);}
        void initialize(){level.getChunkAt(BlockPos.containing(origin));alphaSwap=new Swap(game,alpha);betaSwap=new Swap(game,beta);for(var p:List.of(alpha,beta)){p.closeContainer();p.getInventory().clearContent();p.removeAllEffects();p.setGameMode(GameType.SURVIVAL);p.setNoGravity(true);p.entityTags().remove("sin_greed_active");p.entityTags().remove("spectator");game.items().magic().inventoryChanged(p);}game.items().magic().flushCleansing();place();lastTick=game.server().getTickCount();clearPackets();}
        Recording a(){return alphaSwap.recorder;}Recording b(){return betaSwap.recorder;}
        void clearPackets(){a().sent.clear();b().sent.clear();}
        void clearEffects(){game.items().psycho().clearEffects(alpha);game.items().psycho().clearEffects(beta);}
        void place(){alpha.teleportTo(level,origin.x+10,origin.y,origin.z,Set.of(),0,0,true);beta.teleportTo(level,origin.x,origin.y,origin.z,Set.of(),0,0,true);}
        ItemEntity drop(LbcFeedbackDropItem.Kind kind,int count){var item=token(level,origin,count,alpha,kind);tokens.add(item);return item;}
        void activate(LbcFeedbackDropItem.Kind kind){var item=drop(kind,2);require(game.items().specialDrops().spawn(item) && item.getItem().getCount()==1,"shared source dispatch/single debit "+kind);require(!game.items().specialDrops().spawn(item) && item.getItem().getCount()==1,"duplicate same tick rejected "+kind);item.discard();}
        void presentation(){for(var kind:LbcFeedbackDropItem.Kind.values()){var stack=new ItemStack(kind.item());var flags=stack.get(DataComponents.CUSTOM_DATA).copyTag();require(flags.size()==2 && flags.getIntOr(kind.flag(),0)==1 && flags.getIntOr("drop",0)==1 && LbcFeedbackDropItem.kind(stack)==kind,"exact triggerflags "+kind);String key=kind==LbcFeedbackDropItem.Kind.YAMETE?"drop_yamete_kudasai":"trap_died_from_cum";require(stack.getHoverName().getContents() instanceof net.minecraft.network.chat.contents.TranslatableContents name && name.getKey().equals(key) && !stack.getHoverName().getStyle().isItalic() && stack.getHoverName().getStyle().getColor().getValue()==0xffff55,"exact source name "+kind);var lore=stack.get(DataComponents.LORE).lines();require(lore.size()==1 && lore.getFirst().getContents() instanceof net.minecraft.network.chat.contents.TranslatableContents name && name.getKey().equals("trap_desc") && !lore.getFirst().getStyle().isItalic() && lore.getFirst().getStyle().getColor().getValue()==0xffffff,"exact source lore "+kind);require(Identifier.parse(kind==LbcFeedbackDropItem.Kind.YAMETE?"lbc:drop_not_trap":"lbc:drop_trap").equals(stack.get(DataComponents.ITEM_MODEL)) && (kind==LbcFeedbackDropItem.Kind.YAMETE?!stack.has(DataComponents.TOOLTIP_STYLE):Identifier.parse("lbc:tier_ff").equals(stack.get(DataComponents.TOOLTIP_STYLE))),"exact source tier/model "+kind);var leaf=game.lbc().rollTable(level,origin,alpha,kind==LbcFeedbackDropItem.Kind.YAMETE?"lbc:ported/yamete_drop":"lbc:ported/death_lust_drop");require(leaf.size()==1 && ItemStack.isSameItemSameComponents(stack,leaf.getFirst()),"native public leaf "+kind);var provider=(net.fabricmc.fabric.api.networking.v1.context.PacketContextProvider)alphaSwap.recorder;require(eu.pb4.polymer.common.api.PolymerCommonUtils.getPlayer(provider.getPacketContext())==alpha,"recording connection resolves Polymer recipient");net.fabricmc.fabric.api.networking.v1.context.PacketContext.runWithContext(provider,()->{var proxy=eu.pb4.polymer.core.api.item.PolymerItemUtils.getPolymerItemStack(stack,net.minecraft.world.item.TooltipFlag.NORMAL,provider.getPacketContext(),alpha.registryAccess());require(proxy.is(Items.REPEATING_COMMAND_BLOCK) && Objects.equals(stack.get(DataComponents.ITEM_MODEL),proxy.get(DataComponents.ITEM_MODEL)) && ItemStack.matches(stack,eu.pb4.polymer.core.api.item.PolymerItemUtils.getRealItemStack(proxy,provider.getPacketContext(),alpha.registryAccess())),"actual Polymer projection/authoritative roundtrip "+kind);});}for(var item:List.of(Items.BARRIER,Items.REPEATING_COMMAND_BLOCK,Items.PAPER))require(!LbcFeedbackDropItem.matches(new ItemStack(item)),"unflagged lookalike rejected");}
        void yamete(Recording recorder,boolean audible){var particles=recorder.sent.stream().filter(ClientboundLevelParticlesPacket.class::isInstance).map(ClientboundLevelParticlesPacket.class::cast).filter(p->p.particle().getType()==ParticleTypes.FALLING_WATER || p.particle().getType()==ParticleTypes.EFFECT).toList();require(particles.size()==2,"exact two native Yamete particle packets");var water=particles.get(0);var spell=particles.get(1);require(water.particle().getType()==ParticleTypes.FALLING_WATER && water.count()==100 && spell.particle().getType()==ParticleTypes.EFFECT && spell.count()==10,"source100water/10spell ordered counts");for(var p:particles)require(p.x()==origin.x && p.y()==origin.y && p.z()==origin.z && p.xDist()==.5f && p.yDist()==.5f && p.zDist()==.5f && p.xMaxSpeed()==1 && p.yMaxSpeed()==1 && p.zMaxSpeed()==1 && !p.overrideLimiter() && !p.alwaysShow() && p.randomizationType()==ClientboundLevelParticlesPacket.RandomizationType.DEFAULT,"native particle origin/spread/speed/default delivery flags");require(spell.particle() instanceof SpellParticleOption,"native spell particle payload");var buffer=io.netty.buffer.Unpooled.buffer();try{SpellParticleOption.streamCodec(ParticleTypes.EFFECT).encode(buffer,(SpellParticleOption)spell.particle());require(buffer.readInt()==-1 && buffer.readFloat()==1,"native spell default color-1/power1");}finally{buffer.release();}var sound=sounds(recorder,"minecraft:lbcsounds.yametekudasai");require(sound.size()==(audible?1:0),"native Yamete MASTER range16 audience");for(var p:sound)require(p.getSource()==SoundSource.MASTER && p.getVolume()==1 && p.getPitch()==1 && Math.abs(p.getX()-origin.x)<=.125 && Math.abs(p.getY()-origin.y)<=.125 && Math.abs(p.getZ()-origin.z)<=.125,"Yamete exact sound packet source/volume/pitch/location quantization");}
        void deathPackets(Recording target,Recording other,ServerPlayer victim){var title=titles(target);require(title.size()==2 && title.stream().allMatch(t->t.text().getString().equals("\uE203") && t.text().getString().codePointCount(0,t.text().getString().length())==1),"two native single U+E203 title sends");require(titles(other).isEmpty(),"titles target-only");var sound=sounds(target,"minecraft:lbcsounds.ultrascream");require(sound.size()==1 && sounds(other,"minecraft:lbcsounds.ultrascream").isEmpty(),"ultrascream target-only");var p=sound.getFirst();require(p.getVolume()==10_000_000f && p.getPitch()==1 && p.getSource()==SoundSource.MASTER && Math.abs(p.getX()-victim.getX())<=.125 && Math.abs(p.getY()-victim.getY())<=.125 && Math.abs(p.getZ()-victim.getZ())<=.125,"source private MASTER1e7 sound");for(var recorder:List.of(target,other)){var messages=broadcasts(recorder);require(messages.size()==1 && !messages.getFirst().overlay(),"broadcast arrives once at both actual listeners");var content=messages.getFirst().content();require(content.getSiblings().size()==2 && content.getSiblings().getFirst().getString().equals(victim.getDisplayName().getString()) && content.getSiblings().get(1).getStyle().getColor().getValue()==0xaa0000,"victim display name plus exact dark-red RP translation key (leading space remains client translation)");}require(packetIndex(target,title.getFirst())<target.sent.indexOf(broadcasts(target).getFirst()) && target.sent.indexOf(broadcasts(target).getFirst())<packetIndex(target,title.get(1)) && packetIndex(target,title.get(1))<target.sent.indexOf(sound.getFirst()),"source title/affliction/broadcast/title/sound packet order");}
        void immediate(){presentation();place();clearPackets();activate(LbcFeedbackDropItem.Kind.YAMETE);yamete(a(),true);yamete(b(),true);require(titles(a()).isEmpty() && titles(b()).isEmpty(),"Yamete does not send titles");alpha.teleportTo(level,origin.x+17,origin.y,origin.z,Set.of(),0,0,true);clearPackets();activate(LbcFeedbackDropItem.Kind.YAMETE);yamete(a(),false);yamete(b(),true);place();
            clearPackets();float hpA=alpha.getHealth(),hpB=beta.getHealth();activate(LbcFeedbackDropItem.Kind.DEATH_LUST);deathPackets(b(),a(),beta);require(game.items().psycho().effectValue(beta,"twitching")==1000 && game.items().psycho().effectValue(alpha,"twitching")==0 && beta.getHealth()==hpB && alpha.getHealth()==hpA,"accepted exact1000 native counter units without commented-out kill");clearEffects();
            beta.entityTags().add("sin_greed_active");try{clearPackets();var t=drop(LbcFeedbackDropItem.Kind.DEATH_LUST,2);require(game.items().feedbackDrops().target(t)==alpha,"Greed filtered before nearest, thrower remains eligible");require(game.items().specialDrops().spawn(t) && t.getItem().getCount()==1,"Greed skips recipient but debits once");t.discard();deathPackets(a(),b(),alpha);require(game.items().psycho().effectValue(alpha,"twitching")==1000 && game.items().psycho().effectValue(beta,"twitching")==0,"self native Psycho allowed");}finally{beta.entityTags().remove("sin_greed_active");clearEffects();}
            var board=game.server().getScoreboard();var oldA=alpha.getTeam();var oldB=beta.getTeam();require(board.getPlayerTeam("codex_feedback_probe")==null,"fixture team free");var team=board.addPlayerTeam("codex_feedback_probe");try{board.addPlayerToTeam(alpha.getScoreboardName(),team);board.addPlayerToTeam(beta.getScoreboardName(),team);clearPackets();activate(LbcFeedbackDropItem.Kind.DEATH_LUST);deathPackets(b(),a(),beta);require(game.items().psycho().effectValue(beta,"twitching")==1000,"allied target remains source eligible");}finally{clearEffects();board.removePlayerTeam(team);if(oldA!=null)board.addPlayerToTeam(alpha.getScoreboardName(),oldA);if(oldB!=null)board.addPlayerToTeam(beta.getScoreboardName(),oldB);}
            beta.setGameMode(GameType.SPECTATOR);try{clearPackets();var t=drop(LbcFeedbackDropItem.Kind.DEATH_LUST,1);require(game.items().feedbackDrops().target(t)==alpha && game.items().specialDrops().spawn(t),"native Spectator excluded before nearest");deathPackets(a(),b(),alpha);t.discard();}finally{beta.setGameMode(GameType.SURVIVAL);beta.setNoGravity(true);clearEffects();}
            for(String tag:List.of("spectator","rcdenyalways","strict_map_object","sauvojen_tuntija","magic_academy","transformator")){beta.entityTags().add(tag);try{var t=drop(LbcFeedbackDropItem.Kind.DEATH_LUST,1);require(game.items().feedbackDrops().target(t)==alpha,"protected nearest excluded before selector "+tag);clearPackets();require(game.items().specialDrops().spawn(t),"protected target fallback dispatch "+tag);deathPackets(a(),b(),alpha);t.discard();}finally{beta.entityTags().remove(tag);clearEffects();}}
            for(int type:List.of(5,6)){clearEffects();var artifact=new ItemStack(LbcMagic.MYSTICAL_ARTIFACT);var flags=new net.minecraft.nbt.CompoundTag();flags.putInt("mystical",1);flags.putInt("type",type);artifact.set(DataComponents.CUSTOM_DATA,CustomData.of(flags));beta.getInventory().setItem(0,artifact);game.items().magic().inventoryChanged(beta);try{clearPackets();activate(LbcFeedbackDropItem.Kind.DEATH_LUST);deathPackets(b(),a(),beta);require(game.items().psycho().effectValue(beta,"twitching")== (type==6?0:1000),"custom-status cleansing type6 rejects while type5 keeps native-debuff-only policy; feedback independent "+type);}finally{beta.getInventory().clearContent();game.items().magic().inventoryChanged(beta);game.items().magic().flushCleansing();clearEffects();}}
            alpha.entityTags().add("sin_greed_active");beta.entityTags().add("sin_greed_active");try{clearPackets();var t=drop(LbcFeedbackDropItem.Kind.DEATH_LUST,2);require(game.items().feedbackDrops().target(t)==null,"isolated match has no eligible recipient");require(game.items().specialDrops().spawn(t) && t.getItem().getCount()==1,"no eligible recipient still debits");t.discard();require(titles(a()).isEmpty() && titles(b()).isEmpty() && broadcasts(a()).isEmpty() && broadcasts(b()).isEmpty() && sounds(a(),"minecraft:lbcsounds.ultrascream").isEmpty() && sounds(b(),"minecraft:lbcsounds.ultrascream").isEmpty(),"empty selector sends no death feedback");}finally{alpha.entityTags().remove("sin_greed_active");beta.entityTags().remove("sin_greed_active");}
            clearPackets();var both=drop(LbcFeedbackDropItem.Kind.YAMETE,2);var flags=both.getItem().get(DataComponents.CUSTOM_DATA).copyTag();flags.putInt("death_from_lust",1);both.getItem().set(DataComponents.CUSTOM_DATA,CustomData.of(flags));require(game.items().specialDrops().spawn(both) && both.getItem().getCount()==1,"two feedback flags share one debit");yamete(b(),true);deathPackets(b(),a(),beta);require(b().sent.indexOf(sounds(b(),"minecraft:lbcsounds.yametekudasai").getFirst())<b().sent.indexOf(titles(b()).getFirst()),"Yamete precedes Death Lust in source order");both.discard();clearEffects();
            var fake=drop(LbcFeedbackDropItem.Kind.YAMETE,2);fake.makeFakeItem();require(!game.items().specialDrops().spawn(fake) && fake.getItem().getCount()==2,"native give visual no activation");fake.discard();var stale=drop(LbcFeedbackDropItem.Kind.DEATH_LUST,2);stale.entityTags().add("skywars2.items.stale-fixture");require(!game.items().specialDrops().spawn(stale) && stale.getItem().getCount()==2,"stale epoch no debit");stale.discard();var remote=drop(LbcFeedbackDropItem.Kind.YAMETE,2);int x=(BlockPos.containing(origin).getX()>>4)+128,z=(BlockPos.containing(origin).getZ()>>4)+128;while(level.getChunkSource().getChunkNow(x,z)!=null)x+=128;remote.setPos(x*16+8,origin.y,z*16+8);require(!game.items().specialDrops().spawn(remote) && remote.getItem().getCount()==2 && level.getChunkSource().getChunkNow(x,z)==null,"unloaded source no load/debit");remote.discard();
            var added=new ArrayList<Entity>();for(var e:level.getAllEntities())if(!existing.contains(e) && !(e instanceof ServerPlayer) && !(e instanceof ItemEntity))added.add(e);require(added.isEmpty(),"feedback creates no extra actors");clearPackets();
        }
        boolean step(){require(game.playing(),"actual match retained");int now=game.server().getTickCount();if(now==lastTick)return false;lastTick=now;switch(phase){
            case 0->{immediate();stack=drop(LbcFeedbackDropItem.Kind.DEATH_LUST,2);phase++;}
            case 1->{require(stack.getItem().getCount()==1 && game.items().psycho().effectValue(beta,"twitching")==1000,"first native tick one unit/1000counter");phase++;}
            case 2->{require(stack.isRemoved() && game.items().psycho().effectValue(beta,"twitching")>=1999 && game.items().psycho().effectValue(beta,"twitching")<=2000,"next native tick one final unit and additive counter (not durationticks)");counter=game.items().psycho().effectValue(beta,"twitching");game.items().timeStop().begin(level,200);paused=drop(LbcFeedbackDropItem.Kind.YAMETE,2);wait=0;phase++;}
            case 3->{require(paused.getItem().getCount()==2 && game.items().psycho().effectValue(beta,"twitching")==counter,"actual Stand pauses pending debit and Psycho counter");if(++wait>=3){paused.discard();game.items().timeStop().end(level);wait=0;phase++;}}
            case 4->{if(++wait>=4){require(game.items().psycho().effectValue(beta,"twitching")<counter && game.items().psycho().effectValue(beta,"twitching")>=counter-3,"native thaw decrements counter at two-tick cadence");return true;}}
            default->throw new IllegalStateException("Feedback phase "+phase);
        }return false;}
        public void close(){close(false);}
        void close(boolean keepPsycho){try{if(!keepPsycho){game.items().timeStop().end(level);clearEffects();}tokens.forEach(Entity::discard);alphaState.restore(game);betaState.restore(game);game.items().magic().inventoryChanged(alpha);game.items().magic().inventoryChanged(beta);game.items().magic().flushCleansing();}finally{if(betaSwap!=null)betaSwap.close();if(alphaSwap!=null)alphaSwap.close();}}
    }
    private static void failure(State state,Throwable error){try{state.close();}catch(Throwable cleanup){error.addSuppressed(cleanup);}finally{running=null;}}
    public static void run(GameController game){require(running==null,"already running");running=new State(game);try{running.initialize();}catch(RuntimeException|Error error){failure(running,error);throw error;}}
    public static void tick(GameController game){if(running==null)return;var state=running;try{if(state.step()){state.close();running=null;SkyWars2.LOGGER.info("[check] PASS feedback-drops");}}catch(Throwable error){failure(state,error);SkyWars2.LOGGER.error("[check] FAIL feedback-drops",error);}}
    public static void stopProbe(GameController game){game.items().timeStop().end(game.maps().level());var state=new State(game);try{state.initialize();state.activate(LbcFeedbackDropItem.Kind.DEATH_LUST);require(game.items().psycho().effectValue(state.beta,"twitching")==1000,"actual accepted Twitching retained for global stop");stopVictim=state.beta;state.close(true);game.items().timeStop().begin(state.level,200);}catch(RuntimeException|Error error){failure(state,error);throw error;}require(game.items().psycho().effectValue(stopVictim,"twitching")==1000,"restoration retains accepted native Psycho until real stop");stopEpoch=game.items().epoch();var alpha=game.server().getPlayerList().getPlayer(GameChecks.offlineUuid("TestAlpha"));stopToken=token(game.maps().level(),new Vec3(alpha.getX(),280,alpha.getZ()),3,alpha,LbcFeedbackDropItem.Kind.YAMETE);require(!game.items().specialDrops().spawn(stopToken) && stopToken.getItem().getCount()==3,"pending feedback token under actual freeze");SkyWars2.LOGGER.info("[check] PASS feedback-drops-stop-probe");}
    public static void cleanup(GameController game){require(stopEpoch!=null && !game.items().currentEpoch(stopEpoch) && stopToken!=null && stopToken.getItem().getCount()==3 && game.items().psycho().effectValue(stopVictim,"twitching")==0,"global stop invalidates epoch and clears accepted Psycho without debit");require(!game.items().specialDrops().spawn(stopToken),"stopped feedback token cannot replay");stopToken.discard();stopToken=null;stopEpoch=null;stopVictim=null;SkyWars2.LOGGER.info("[check] PASS feedback-drops-cleanup");}
}
